def climb_stairs(n: int) -> int:
    if n <= 1:
        return 1
    # Counts for steps 0 and 1.
    prev2, prev1 = 1, 1
    for step in range(2, n + 1):
        current = prev2 + prev1
        prev2, prev1 = prev1, current
    return prev1

solution.java:
import java.math.BigInteger;

class Solution {
    public BigInteger climbStairs(int n) {
        if (n <= 1) {
            return BigInteger.ONE;
        }
        // Exact counts without fixed-width integer overflow.
        BigInteger prev2 = BigInteger.ONE;
        BigInteger prev1 = BigInteger.ONE;
        for (long step = 2; step <= n; step++) {
            BigInteger current = prev2.add(prev1);
            prev2 = prev1;
            prev1 = current;
        }
        return prev1;
    }
}

