function climbStairs(n) {
    if (n <= 1) return 1n;
    // BigInt keeps counts exact; the return value is a BigInt.
    let prev2 = 1n;
    let prev1 = 1n;
    for (let step = 2; step <= n; step++) {
        const current = prev2 + prev1;
        prev2 = prev1;
        prev1 = current;
    }
    return prev1;
}
